miniLab.verifyScript:
# Goose Contributor Academy - Unit 1 exam miniLab: Architecture dossier
# Checks the learner-written dossier.md covers the required traces with evidence.
param([string]$GooseRepo = $env:GOOSE_REPO)

$ErrorActionPreference = "Stop"
$fails = 0
$passes = 0
if (-not $GooseRepo) { $GooseRepo = "C:\Users\admin\projects\goose" }

function Check {
    param([string]$Name, [bool]$Ok, [string]$Detail)
    if ($Ok) { Write-Host "[PASS]  $Name"; $script:passes++ }
    else { Write-Host "[FAIL]  $Name - $Detail"; $script:fails++ }
}

$d = Join-Path (Get-Location) "dossier.md"
$raw = if (Test-Path $d) { Get-Content $d -Raw } else { $null }
Check "dossier.md exists" ($null -ne $raw) "write the module map + 3 traces first"
if ($null -eq $raw) { Write-Host "VERIFY FAILED - 0/9 checks passed"; exit 1 }

$m = @{
  'goose-provider-types' = 'goose-provider-types';
  'MessageContentBlock' = 'MessageContentBlock';
  'StateMachine' = 'StateMachine';
  'GooseEffect' = 'GooseEffect';
  'PermissionCheckResult' = 'PermissionCheckResult';
  'ExtensionManager' = 'ExtensionManager';
  'normalize_input_schema' = 'normalize_input_schema';
  'compact_messages' = 'compact_messages';
  'OTEL_EXPORTER_OTLP_PROTOCOL' = 'OTEL_EXPORTER_OTLP_PROTOCOL'
}
foreach ($k in $m.Keys) {
    Check "dossier mentions $($m[$k])" ($raw -match [regex]::Escape($m[$k])) "missing term $($m[$k])"
}

$f = @(
  @('GOOSE_MAX_TURNS', 'GOOSE_MAX_TURNS'),
  @('ToolRequest', 'ToolRequest'),
  @('deserialize_sanitized_content|deserialize_with', 'message deserializer'),
  @('goose_mode == GooseMode::Chat|GooseMode::Chat', 'Chat mode gate'),
  @('dispatch_tool_call', 'dispatch'),
  @('agent.rs', 'agent.rs citation'),
  @('OTEL_EXPORTER_OTLP_PROTOCOL=http/protobuf|http/protobuf', 'http/protobuf fix')
)
foreach ($e in $f) {
    if ($raw -notmatch $e[0]) { Write-Host "[FAIL]  $($e[1]) evidence MISSING"; $script:fails++ }
    else { Write-Host "[PASS]  $($e[1]) evidence present"; $script:passes++ }
}

Write-Host ""
if ($fails -eq 0) {
    Write-Host "VERIFY PASSED $passes/$($passes + $fails)"
    exit 0
} else {
    Write-Host "VERIFY FAILED - $fails of $($passes + $fails) checks failed"
    exit 1
}
